// A whole Rhai program: functions, arrays, loops, nested maps. Runs on any graph and can be
// re-run: it first removes the services an earlier run created.
g.v().has_label("service").drop().to_list();

fn add_service(g, name, team, image, replicas, ports) {
    g.add_v("service")
        .property("name", name)
        .property("config", #{
            runtime: #{ image: image, replicas: replicas, ports: ports },
            owner:   #{ team: team, oncall: [team + "-primary", team + "-secondary"] }
        })
        .next()
}

let services = [
    ["gateway",  "edge",     "nginx:1.27",    2, [80, 443]],
    ["api",      "core",     "api:4.1",       3, [8080]],
    ["billing",  "payments", "billing:2.0",   1, [8081, 9090]],
    ["postgres", "data",     "postgres:16",   1, [5432]],
];
for s in services {
    add_service(g, s[0], s[1], s[2], s[3], s[4]);
}

let deps = [["gateway", "api"], ["api", "billing"], ["api", "postgres"], ["billing", "postgres"]];
for d in deps {
    g.v().has("name", d[0]).add_e("depends_on").to(__.v().has("name", d[1])).to_list();
}

// Everything api depends on, with values read deep inside the nested config.
g.v().has("name", "api").out("depends_on")
    .project("service", "image", "first_port", "team")
    .by("name")
    .by(jpath("config.runtime.image"))
    .by(jpath("config.runtime.ports[0]"))
    .by(jpath("config.owner.team"))

// Data terminals (to_list(), next()) return plain Rhai values you can compute with.
let people = g.v().has_label("person").value_map("name", "age").to_list();
let total = 0;
let oldest = "";
let max_age = 0;
for p in people {
    let age = p.age[0];
    total += age;
    if age > max_age { max_age = age; oldest = p.name[0]; }
}
#{ people: people.len(), average_age: total / people.len(), oldest: oldest }

// Fake(seed): reproducible English test data. Change the seed for other values; Fake()
// without a seed picks one (read it with f.seed()). Nothing is written to the graph.
let f = Fake(7);
let rows = [];
for i in 0..10 {
    let name = f.full_name();
    rows.push(#{
        name:    name,
        email:   f.email(name),
        job:     f.job_title(),
        company: f.company(),
        address: f.address(),
        uuid:    f.uuid()
    });
}
rows

// A reproducible test graph: companies with a management tree each, people with Fake data
// and a Lorem ipsum "about" text, cities and random "knows" edges. Change the parameters
// and run again; the same parameters always give the same graph. REPLACES the current graph.
// Sizes: people = companies * (fanout^(depth+1) - 1) / (fanout - 1) (with fanout > 1);
// companies 3, depth 6, fanout 4 gives 16 383 people.

// ---- parameters ------------------------------------------------------------------------
let seed        = 42;   // the same seed gives the same graph
let companies   = 3;    // one management tree per company
let depth       = 4;    // levels of reports below each CEO
let fanout      = 3;    // direct reports per manager
let knows_edges = 500;  // random "knows" pairs (a pair of one person is skipped)
let cities      = 12;   // cities people live in
let about_min   = 200;  // "about": Lorem ipsum text of a random length, in bytes, from
let about_max   = 5000; //   about_min to about_max (0 and 0: no "about" property)
let compress_about = true; // keep "about" compressed in memory (a compression rule)
// ----------------------------------------------------------------------------------------

// The rule is (re)defined after the data, so its pass builds the dictionary from it.
if g.compressions().filter(|c| c.name == "person_about").len() > 0 {
    g.drop_compression("person_about");
}
g.v().drop().to_list();

let f      = Fake(seed);
let people = f.fork("people");   // separate streams: a change in one part of the graph
let social = f.fork("social");   // does not shift the values of the others
let about  = #{ text: f.fork("about"), min: about_min, max: about_max };

let city_ids = [];
for i in 0..cities {
    city_ids.push(g.add_v("city").property("name", f.city())
        .property("state", f.state_abbr()).id().next());
}

// A person with Fake data, working at `company`, living in a random city. `p` is shared with
// the caller: every call draws new values.
fn hire(g, p, about, company, title, cities) {
    let name = p.full_name();
    let person = g.add_v("person")
        .property("name", name)
        .property("email", p.email(name))
        .property("title", title)
        .property("age", p.int(21, 67));
    if about.max > 0 {
        person = person.property("about", about.text.lorem(about.min, about.max));
    }
    let id = person.id().next();
    g.v(id).add_e("works_at").to(g.v(company)).to_list();
    g.v(id).add_e("lives_in").to(g.v(p.pick(cities))).to_list();
    id
}

let person_ids = [];
for c in 0..companies {
    let company = g.add_v("company").property("name", f.company())
        .property("domain", f.domain_name()).id().next();
    let level = [hire(g, people, about, company, "CEO", city_ids)];
    person_ids += level;
    for d in 0..depth {
        let reports = [];
        for manager in level {
            for r in 0..fanout {
                let id = hire(g, people, about, company, people.job_title(), city_ids);
                g.v(id).add_e("reports_to").to(g.v(manager)).to_list();
                reports.push(id);
            }
        }
        person_ids += reports;
        level = reports;
    }
}

// Pick by index: pick() and sample() get a copy of the array, which is slow for a large one.
for k in 0..knows_edges {
    let a = person_ids[social.int(0, person_ids.len() - 1)];
    let b = person_ids[social.int(0, person_ids.len() - 1)];
    if a != b {
        g.v(a).add_e("knows").property("since", social.int(1990, 2026)).to(g.v(b)).to_list();
    }
}

if compress_about && about_max > 0 {
    g.define_compression(#{name: "person_about", label: "person", path: "about"});
}

#{
    vertices: g.v().group_count().by(T.label).next(),
    edges:    g.e().group_count().by(T.label).next(),
    longest_chain: g.v().has_label("person").has("title", "CEO").limit(1)
        .repeat(__.in("reports_to")).emit().path().count(Scope.local).max().next(),
    // the plain and the stored (compressed) bytes of "about"; compare compress_about = false
    memory: g.memory_usage()
}

// Give every person a nested profile (objects inside objects, arrays), then read deep values.
let profiles = #{
    marko: #{ city: "Berlin", country: "DE", lat: 52.52, skills: ["gremlin", "rust"] },
    vadas: #{ city: "Paris",  country: "FR", lat: 48.86, skills: ["sql"] },
    josh:  #{ city: "Munich", country: "DE", lat: 48.14, skills: ["rust", "wasm", "go"] },
    peter: #{ city: "Oslo",   country: "NO", lat: 59.91, skills: ["java"] },
};
for name in profiles.keys() {
    let p = profiles[name];
    g.v().has("name", name).property("profile", #{
        address: #{ city: p.city, country: p.country, geo: #{ lat: p.lat } },
        skills: p.skills,
    }).to_list();
}

// Filter, sort and project on values deep inside the object.
g.v().has_label("person")
    .has(jpath("profile.address.geo.lat"), P.lt(55.0))
    .order().by(jpath("profile.address.geo.lat"), Order.desc)
    .project("name", "city", "first_skill", "last_skill")
    .by("name")
    .by(jpath("profile.address.city"))
    .by(jpath("profile.skills[0]"))
    .by(jpath("profile.skills[-1]"))

// Group by a nested key.
g.v().has_label("person").property("profile", #{ address: #{ country: "DE" } }).to_list();
g.v().has("name", "vadas").property(jpath("profile.address.country"), "FR").to_list();
g.v().has_label("person").group_count().by(jpath("profile.address.country"))

// Edit inside a nested object without rewriting the whole property.
g.v().has("name", "marko").property("profile", #{
    address: #{ city: "Berlin", zip: "10115" },
    skills: ["gremlin", "rust"],
}).to_list();

g.v().has("name", "marko")
    .property(jpath("profile.address.city"), "Hamburg")   // replace a leaf
    .property(jpath("profile.skills[2]"), "wasm")         // append: index == length
    .property(jpath("profile.links.github"), "okram")     // missing objects are created
    .remove_property(jpath("profile.address.zip"))        // remove one nested key
    .values("profile")

// File tree sample: walk the tree with a filesystem-style glob pattern.
g.v("root").glob_path("**/author/*/some/*.rs").by("name").by(["directory", "file"])
  .order().by(T.id).id()

// The built-in embedder hash-ngram/1 turns text into vectors inside the engine: no model file,
// no network, the same bits everywhere. It compares spelling (character n-grams), not meaning:
// good for typos, word forms and fuzzy lookup.
// Re-runnable: first remove what an earlier run created.
g.v().has_label("product").drop().iterate();
for name in ["Wireless headphones", "Bluetooth speaker", "Mechanical keyboard",
             "Wireless mouse", "USB-C charger", "Noise cancelling earbuds"] {
  g.add_v("product").property("name", name).iterate();
}

// 1. Attach a schema (mode open): the schema records which model made each vector property.
g.set_schema(g.infer_schema(), SchemaMode.open);

// 2. Embed the property "name" of every product into "emb". embedder: a name that
//    g.embedders() lists (without it, the default runs: here hash-ngram/1). It also declares
//    "emb" in the schema: a vector with "embedder": "hash-ngram/1", the embedder's model.
g.embed_property(#{label: "product", from: "name", to: "emb", embedder: "hash-ngram/1"});

// 3. A text query: embedded with the model the schema names for product.emb. Typos are fine.
g.v().has_label("product")
 .nearest("emb", "wirless hedphones", 3)
 .values("name")

// Configure the schema yourself: a vector property with element, dimension, metric and the
// embedder that fills it. hash-ngram/1 gives 256 f32 components, compared by cosine.
// Re-runnable: first remove what an earlier run created.
g.v().has_label("city").drop().iterate();
g.set_schema(#{
  vertices: #{
    city: #{schema: #{
      type: "object",
      required: ["name"],
      properties: #{
        name: #{type: "string"},
        country: #{type: "string"},
        name_vec: #{type: "array", format: "vector", element: "f32", dimension: 256,
                    metric: "cosine", embedder: "hash-ngram/1"}
      }
    }}
  }
}, SchemaMode.open);

for c in [["München", "DE"], ["Muenchen Hbf", "DE"], ["Moscow", "RU"], ["Москва", "RU"],
          ["Köln", "DE"], ["Cologne", "DE"], ["San Francisco", "US"]] {
  g.add_v("city").property("name", c[0]).property("country", c[1]).iterate();
}
g.embed_property(#{label: "city", from: "name", to: "name_vec"});

// The declaration the query relies on:
// g.get_schema()["vertices"]["city"]["schema"]["properties"]["name_vec"]

// Fuzzy lookup of a misspelled name, with the score.
g.v().has_label("city")
 .nearest("name_vec", "Munchen", 3)
 .project("name", "score")
   .by("name")
   .by(__.similarity("name_vec", "Munchen"))

// Deduplication: pairs of customer names that are spelled almost alike.
// embed() computes a vector without storing it; similarity() scores two vectors.
// Re-runnable: first remove what an earlier run created.
g.v().has_label("customer").drop().iterate();
for n in ["Jonathan Smith", "Jonathon Smith", "J. Smith", "Maria Garcia",
          "María García", "Mario Garcia", "Wei Zhang"] {
  g.add_v("customer").property("name", n).iterate();
}
let names = g.v().has_label("customer").values("name").to_list();
let rows = [];
for i in 0..names.len() {
  for j in (i + 1)..names.len() {
    let score = g.inject(embed(names[i])).similarity(embed(names[j])).next();
    if score > 0.5 { rows.push(#{a: names[i], b: names[j], score: score}); }
  }
}
// "María García" does not pair with "Maria Garcia": hash-ngram/1 does not fold accents.
rows

// Toy embeddings with three axes: [animals, food, technology].
// Re-runnable: first remove what an earlier run created.
