// Only documents from 2025 on are ranked.
g.v().has_label("doc")
 .has("year", P.gte(2025))
 .nearest("emb", vector([1.0, 0.0, 0.0]), 3)
 .project("title", "year").by("title").by("year")

// Documents with toy embeddings [animals, food, technology],
// their authors (wrote) and topics (about).
// Re-runnable: first remove what an earlier run created.
g.v().has_label("doc", "person", "topic").drop().iterate();
for d in [
  ["Cats and dogs",      "Ada",  "pets",        [0.9, 0.1, 0.0]],
  ["Feeding your cat",   "Ada",  "pets",        [0.6, 0.7, 0.0]],
  ["Pasta at home",      "Ben",  "cooking",     [0.0, 0.9, 0.1]],
  ["Robot chefs",        "Cleo", "cooking",     [0.1, 0.6, 0.8]],
  ["Rust for beginners", "Cleo", "programming", [0.0, 0.0, 1.0]],
] {
  g.merge_v(#{"T.label": "person", name: d[1]}).as("a")
   .merge_v(#{"T.label": "topic", name: d[2]}).as("t")
   .add_v("doc").property("title", d[0])
   .property("emb", vector(d[3])).as("d")
   .add_e("about").to("t")
   .add_e("wrote").from("a").to("d")
   .iterate();
}

// "What should I cook for my cat?" ~ [0.5, 0.8, 0.0]:
// the best hits, then the graph around them as context.
g.v().has_label("doc")
 .nearest("emb", vector([0.5, 0.8, 0.0]), 2)
 .project("title", "author", "topic", "same_topic")
   .by("title")
   .by(__.in("wrote").values("name"))
   .by(__.out("about").values("name"))
   .by(__.as("hit").out("about").in("about")
          .where(P.neq("hit")).values("title").fold())

// The schema declares note.emb as an i8 vector: a written list
// (or an f32 vector) is quantized as it is stored, 1 byte per component.
// Re-runnable: first remove what an earlier run created.
g.v().has_label("note").drop().iterate();
g.patch_schema(#{mode: "open", vertices: #{note: #{schema: #{
  type: "object",
  properties: #{
    emb: #{type: "array", format: "vector", element: "i8", dimension: 3}
  }}}}});
for n in [
  ["Cats and dogs",      [0.9, 0.1, 0.0]],
  ["Pasta at home",      [0.0, 0.9, 0.1]],
  ["Rust for beginners", [0.0, 0.0, 1.0]],
] {
  g.add_v("note").property("title", n[0]).property("emb", n[1]).iterate();
}

// An f32 query searches the i8 vectors.
g.v().has_label("note")
 .project("title", "stored", "score")
   .by("title")
   .by("emb")
   .by(__.similarity("emb", vector([1.0, 0.2, 0.0])))

